def transform(grid):
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            counts = Counter(
                grid[r][c]
                for r in range(br, min(br + 3, len(grid)))
                for c in range(bc, min(bc + 3, len(grid[0])))
                if grid[r][c] != 5
            )
            row.append(counts.most_common(1)[0][0] if counts else 5)
        out.append(row)
    return out
